MODEL (
  name silver.order_item,
  kind FULL,
  grain (order_id, line_no),
  audits (order_item_key_unique, not_null(columns := (order_date)))
);

SELECT
  CAST(index AS BIGINT) AS line_no,
  CAST(CASE
    WHEN SUBSTRING(CAST(created_at AS TEXT), 11) LIKE '%+%'
    OR SUBSTRING(CAST(created_at AS TEXT), 11) LIKE '%-%'
    THEN NULL
    ELSE REPLACE(REPLACE(CAST(created_at AS TEXT), 'T', ' '), 't', ' ')
  END AS TIMESTAMP) AS order_date,
  CAST(order_id AS TEXT) AS order_id,
  CAST(qty AS BIGINT) AS quantity,
  CAST(price AS DECIMAL(12, 4)) AS unit_price,
  CAST([] AS TEXT[]) AS _quality_flags,
  TRUE AS _quality_ok
FROM bronze.shop__order_lines
